fn element_wise_divide(arr1: &Vec<u32>, arr2: &Vec<u32>) -> Vec<u32> {
    assert!(
        arr1.len() == arr2.len(),
        "Input arrays must have the same length"
    );

    let mut result = Vec::with_capacity(arr1.len());

    for (&a, &b) in arr1.iter().zip(arr2.iter()) {
        assert!(b != 0, "Divisor array must not contain zeros");
        let q = a / b;

        // As assumed by the problem statement, q fits in i32 range.
        debug_assert!(q <= i32::MAX as u32);

        result.push(q);
    }

    result
}